// <auto-generated/>
using System;
using Fanex.Age.UI.Components.RefreshCountDown;
using AlphaPlus.User.Models;
using TplNetCore.Element;

/// <summary>
/// Generate refresh count down control
/// </summary>
namespace Fanex.Age.UI.Components
{
    public class RefreshCountDown_Control : IComponent
    {
        #region Const
        const int STEP = 15;
        const String DEFAULT_ID = "CountDown";
        const String DEFAULT_REFRESH_FUNC = "CountDownRefresh";
        #endregion

        #region Variable
        private RefreshCountDown_Template _RefreshCountDownTemplate = null;
        #endregion

        public RefreshCountDown_Control(int initCountDown, String refreshCountDownId, String refreshFunc)
        {
            _RefreshCountDownTemplate = new RefreshCountDown_Template();
            _RefreshCountDownTemplate.initCountDown = initCountDown.ToString();
            _RefreshCountDownTemplate.RefreshCountDownId = refreshCountDownId;
            _RefreshCountDownTemplate.CountDownRefreshFunc = refreshFunc;

            _RefreshCountDownTemplate.ExternalResources.DarkModeName = UserSession.Current.DarkModeName;

            int i = 0;
            int[] mins = GenerateCountDownOption(initCountDown);
            _RefreshCountDownTemplate.Seconds.Clear();
            foreach (int min in mins)
            {
                RefreshCountDown_Seconds_Block block = new RefreshCountDown_Seconds_Block();
                block.i = i.ToString();
                block.SecondNum = min.ToString();
                block.OptionClass = (i < mins.Length) ? "div_min_bottom" : String.Empty;

                _RefreshCountDownTemplate.Seconds.Append(block);
                i++;
            }
        }

        public RefreshCountDown_Control(IElement parent, int initCountDown)
            : this(initCountDown, DEFAULT_ID, DEFAULT_REFRESH_FUNC)
        {
            parent.RegisterComponent("RefreshCountDown_Control", this);
        }
        public RefreshCountDown_Control(IElement parent, int initCountDown, String refreshCountDownId)
            : this(initCountDown, refreshCountDownId, DEFAULT_REFRESH_FUNC)
        {
            parent.RegisterComponent("RefreshCountDown_Control", this);
        }
        public RefreshCountDown_Control(IElement parent, int initCountDown, String refreshCountDownId, String refreshFunc)
            : this(initCountDown, refreshCountDownId, refreshFunc)
        {
            parent.RegisterComponent("RefreshCountDown_Control", this);
        }


        public override string ToString()
        {
            return _RefreshCountDownTemplate != null ? _RefreshCountDownTemplate.ToString() : String.Empty;
        }
        #region Private

        /// <summary>
        /// Return array of allowing step of current initCountDown
        /// </summary>
        /// <param name="initCountDown"></param>
        /// <returns></returns>
        private int[] GenerateCountDownOption(int initCountDown)
        {
            int[] mins = new int[5];
            int count = -2;
            if (initCountDown < STEP)
                count = 0;
            else
                while (initCountDown + (count + 0) * STEP < STEP) count++;

            mins[0] = initCountDown + (count + 0) * STEP;
            mins[1] = initCountDown + (count + 1) * STEP;
            mins[2] = initCountDown + (count + 2) * STEP;
            mins[3] = initCountDown + (count + 3) * STEP;
            mins[4] = initCountDown + (count + 4) * STEP;
            return mins;
        }
        #endregion

        #region IComponent Members

        public void HideLinkedResources()
        {
            _RefreshCountDownTemplate.ExternalResources.Hide();
        }

        #endregion
    }
}